<!DOCTYPE html>
<html>
<head>
  <title>Kanban Board</title>
  <style>
    body { font-family: sans-serif; }
    #board { display: flex; width: 80%; margin: 20px auto; }
    #col-todo, #col-doing, #col-done { background-color: #f0f0f0; padding: 10px; border: 1px solid #ccc; flex: 1; }
    .count { font-weight: bold; margin-bottom: 5px; }
    .card { background-color: white; border: 1px solid #eee; padding: 10px; cursor: grab; }
    .card-del { float: right; background-color: red; color: white; padding: 5px; cursor: pointer; }
    #new-card { width: 200px; padding: 5px; margin-bottom: 10px;}
    #add-card { background-color: #4CAF50; color: white; border: none; padding: 5px 10px; cursor: pointer;}
  </style>
</head>
<body>

  <h1>Kanban Board</h1>

  <div id="board">
    <div id="col-todo" draggable="true">
      <h2>To Do</h2>
      <span class="count">0</span>
      <div id="card-container-todo"></div>
    </div>
    <div id="col-doing" draggable="true">
      <h2>Doing</h2>
      <span class="count">0</span>
      <div id="card-container-doing"></div>
    </div>
    <div id="col-done" draggable="true">
      <h2>Done</h2>
      <span class="count">0</span>
      <div id="card-container-done"></div>
    </div>
  </div>

  <input type="text" id="new-card" placeholder="New card title">
  <button id="add-card">Add Card</button>

  <script>
    const board = document.getElementById('board');
    const colTodo = document.getElementById('col-todo');
    const colDoing = document.getElementById('col-doing');
    const colDone = document.getElementById('col-done');
    const newCardInput = document.getElementById('new-card');
    const addCardButton = document.getElementById('add-card');
    const cardContainerTodo = document.getElementById('card-container-todo');
    const cardContainerDoing = document.getElementById('card-container-doing');
    const cardContainerDone = document.getElementById('card-container-done');

    let cards = JSON.parse(localStorage.getItem('cards')) || [];

    function updateCounts() {
      document.querySelectorAll('.count').forEach(span => {
        span.textContent = cards.filter(card => card.column === span.parentNode.id).length;
      });
    }

    function createCardElement(title, column) {
      const card = document.createElement('div');
      card.classList.add('card');
      card.draggable = true;
      card.textContent = title;

      const delButton = document.createElement('button');
      delButton.classList.add('card-del');
      delButton.textContent = 'Delete';
      card.appendChild(delButton);

      return card;
    }


    function moveCard(draggedCard, dropTarget) {
        const columnId = dropTarget.id;
        const existingCardIndex = cards.findIndex(card => card.element === draggedCard);

        if (existingCardIndex !== -1) {
          cards.splice(existingCardIndex, 1);
        }

        draggedCard.style.opacity = '0.5'; // Visual feedback during drag

        setTimeout(() => {
            draggedCard.style.opacity = '1';
            draggedCard.dataset.column = columnId;
            cards.push({ element: draggedCard, column: columnId });
            updateCounts();
        }, 200);  // Slight delay for drag feedback
    }


    colTodo.addEventListener('dragover', (e) => {
      e.preventDefault();
    });

    colTodo.addEventListener('drop', (e) => {
      const draggedCard = e.dataTransfer.getData('text/html');
      moveCard(document.getElementById(draggedCard), colTodo);
    });

    colDoing.addEventListener('dragover', (e) => {
      e.preventDefault();
    });

    colDoing.addEventListener('drop', (e) => {
      const draggedCard = e.dataTransfer.getData('text/html');
      moveCard(document.getElementById(draggedCard), colDoing);
    });

    colDone.addEventListener('dragover', (e) => {
      e.preventDefault();
    });

    colDone.addEventListener('drop', (e) => {
      const draggedCard = e.dataTransfer.getData('text/html');
      moveCard(document.getElementById(draggedCard), colDone);
    });


    addCardButton.addEventListener('click', () => {
      const title = newCardInput.value.trim();
      if (title) {
        const card = createCardElement(title, 'todo');
        cardContainerTodo.appendChild(card);
        cards.push({ element: card, column: 'todo' });
        updateCounts();
        newCardInput.value = '';
      }
    });

    // Initial load
    updateCounts();
    cards.forEach(card => {
      const newCardElement = createCardElement(card.element.textContent, card.column);
      document.getElementById(card.column).appendChild(newCardElement);
    });
  </script>

</body>
</html>
